"""Reference policy: executable JSON adapter, never reads simulator hidden state."""
import argparse
import base64
import itertools
import kit
import json
import math
import random
import sys
import zlib
from kit import baseline_asks, baseline_match, eligibility


def decide(request, mode='greedy'):
    state = request['state']
    memory = request.get('memory') or {}
    if request['phase'] == 'ask':
        if mode == 'ac':
            try:
                asks = ac_asks(state)
            except Exception:
                asks = []
            return {'asks': asks, 'memory': memory_summary(state)}
        return {'asks': [] if mode == 'no_asks' else baseline_asks(state), 'memory': memory}
    if mode == 'ac':
        return {'pairs': ac_match(state), 'memory': memory_summary(state)}
    if mode != 'random':
        pairs = baseline_match(state)
    else:
        candidates = [m for m in state['members'] if m['available']]
        past = {tuple(sorted((i['user_a'], i['user_b']))) for i in state['introductions']}
        edges = [tuple(sorted((a['member_id'], b['member_id'])))
                 for a, b in itertools.combinations(candidates, 2)
                 if eligibility(a, b)['status'] == 'feasible'
                 and tuple(sorted((a['member_id'], b['member_id']))) not in past]
        random.Random(17 + state['day']).shuffle(edges)
        pairs, used = [], set()
        for pair in edges:
            if not used.intersection(pair):
                pairs.append(list(pair))
                used.update(pair)
    return {'pairs': pairs, 'memory': memory}


# --- Model package (generated blob + pure-Python HistGB inference) ---

# BEGIN GENERATED MODEL BLOB
MODEL_B64 = ''
# END GENERATED MODEL BLOB

_LOADED = {}


def load_model():
    """Decode+validate MODEL_B64 once per distinct blob; None routes to fallback."""
    blob = MODEL_B64
    if blob in _LOADED:
        return _LOADED[blob]
    model = None
    try:
        raw = zlib.decompress(base64.b64decode(blob.encode('ascii')))
        obj = json.loads(raw.decode('utf-8'))
        ok = (isinstance(obj, dict) and obj.get('schema') == 1
              and obj.get('n_features') == 44
              and isinstance(obj.get('feature_keys'), list)
              and len(obj['feature_keys']) == 44
              and math.isfinite(obj.get('floor'))
              and math.isfinite(obj.get('baseline'))
              and isinstance(obj.get('n_iter'), int) and not isinstance(obj.get('n_iter'), bool)
              and 1 <= obj['n_iter'] <= 200
              and isinstance(obj.get('trees'), list) and bool(obj['trees']))
        if ok:
            if obj['n_iter'] != len(obj['trees']):   # binary HGB: one tree per fitted iteration
                ok = False
            for tree in obj['trees']:
                if not tree:
                    ok = False
                    break
                for node in tree:
                    if len(node) not in (1, 5):
                        ok = False
                        break
            model = obj if ok else None
    except Exception:
        model = None
    _LOADED[blob] = model
    return model


def _walk(tree, x):
    """One tree -> raw contribution. Leaf [value]; internal [feat, thr, left, right, missing_left]."""
    i = 0
    while True:
        node = tree[i]
        if len(node) == 1:
            return float(node[0])
        value = x[int(node[0])]
        if value != value:  # NaN -> missing branch
            i = int(node[2]) if node[4] else int(node[3])
        elif value <= float(node[1]):
            i = int(node[2])
        else:
            i = int(node[3])


def _sigmoid(raw):
    if raw >= 0.0:
        return 1.0 / (1.0 + math.exp(-raw))
    e = math.exp(raw)
    return e / (1.0 + e)


def score_row(model, x):
    """Ranking score in (0,1): sigmoid(baseline + sum of leaf values). No lr scaling (A2/C6)."""
    raw = float(model['baseline'])
    for tree in model['trees']:
        raw += _walk(tree, x)
    return _sigmoid(raw)


WEIGHTS = {'relationship_goal': .7, 'relationship_pace': .4,
           'lifestyle': .25, 'conversations': .2}
SOFT = list(kit.SOFT)
HARD = list(kit.HARD)


HIST_METRICS = ('n_intros', 'n_mutual', 'n_dates', 'yes_rate', 'n_missing')

PROFILE_KEYS = ('age_diff', 'age_mean', 'same_zone', 'same_gender', 'arrived_gap')
HARD_KEYS = ('hard_feasible', 'n_hard_missing', 'n_hard_reasons')
WHO_KEYS = ('who_meets_min', 'who_meets_max')
SOFT_MATCH_KEYS = tuple('soft_%s_match' % k for k in SOFT)
SOFT_OBS_KEYS = tuple('soft_%s_observed' % k for k in SOFT)
SOFT_AGG_KEYS = ('soft_match_count', 'soft_observed_pairs',
                 'weighted_soft_score', 'weighted_soft_covered')
TEMPORAL_KEYS = ('day', 'days_since_arrival_mean', 'days_since_arrival_absdiff',
                 'ask_budget')
HIST_KEYS = tuple('hist_%s_%s' % (m, agg) for m in HIST_METRICS for agg in ('mean', 'absdiff'))
COMP_KEYS = ('comp_available', 'comp_available_excl')

FEATURE_KEYS = list(PROFILE_KEYS + HARD_KEYS + WHO_KEYS + SOFT_MATCH_KEYS + SOFT_OBS_KEYS
                    + SOFT_AGG_KEYS + TEMPORAL_KEYS + HIST_KEYS + COMP_KEYS)
FEATURE_GROUPS = {
    'profile': list(PROFILE_KEYS),
    'hard': list(HARD_KEYS),
    'who_to_meet': list(WHO_KEYS),
    'soft': list(SOFT_MATCH_KEYS + SOFT_OBS_KEYS),
    'soft_aggregate': list(SOFT_AGG_KEYS),
    'temporal': list(TEMPORAL_KEYS),
    'history': list(HIST_KEYS),
    'competition': list(COMP_KEYS),
}

NAN = float('nan')






def smoothing(x, n):
    """Laplace-smoothed rate (x+1)/(n+2); never collapses to 0 or 1."""
    return (x + 1.0) / (n + 2.0)


def _visible(state, mid):
    for m in state['members']:
        if m['member_id'] == mid:
            return m
    raise ValueError('member not visible in state: ' + str(mid))


def _field(member, key, t):
    """Observed-at-t value of a field, else None (future observations masked)."""
    value = member['fields'].get(key)
    if value is None:
        return None
    observed = member['field_observed_day'].get(key)
    if observed is None or observed > t:
        return None
    return value


def _feedback_upto(state, t):
    return [e for e in state['feedback'] if e.get('observed_day') is not None
            and e['observed_day'] <= t]


def member_history(state, t, member_id):
    """Per-member statistics from feedback observed at or before t."""
    events = _feedback_upto(state, t)
    by_intro = {}
    for e in events:
        by_intro.setdefault(e['introduction_id'], []).append(e)
    members_of = {i['introduction_id']: (i['user_a'], i['user_b'])
                  for i in state['introductions'] if i['assigned_day'] <= t}
    out = dict(n_intros=0, n_mutual=0, n_dates=0, n_missing=0,
               n_responses=0, n_yes=0, n_second_yes=0)
    for iid, pair in members_of.items():
        if member_id not in pair:
            continue
        out['n_intros'] += 1
        evs = by_intro.get(iid, [])
        rs = [e for e in evs if e['event'] == 'introduction_response']
        if len(rs) == 2 and all(e['value'] == 'yes' for e in rs):
            out['n_mutual'] += 1
        if any(e['event'] == 'date_happened' and e['value'] is True for e in evs):
            out['n_dates'] += 1
    for e in events:
        if e.get('member_id') != member_id:
            continue
        if e['event'] == 'introduction_response':
            out['n_responses'] += 1
            out['n_yes'] += e['value'] == 'yes'
            out['n_missing'] += e.get('missing_reason') == 'no_response'
        elif e['event'] == 'second_meeting_intention':
            out['n_second_yes'] += e['value'] == 'yes'
    out['yes_rate'] = smoothing(out['n_yes'], out['n_responses'])
    return out


def pair_features(state, a_id, b_id, t):
    """Feature vector for pair (a_id, b_id) as known at day t. Symmetric in a/b."""
    a = _visible(state, a_id)
    b = _visible(state, b_id)
    f = {}

    f['age_diff'] = float(abs(a['age'] - b['age']))
    f['age_mean'] = float((a['age'] + b['age']) / 2.0)
    f['same_zone'] = float(a['zone'] == b['zone'])
    f['same_gender'] = float(a['gender'] == b['gender'])
    f['arrived_gap'] = float(abs(a['arrived_day'] - b['arrived_day']))

    elig = kit.eligibility(a, b)
    f['hard_feasible'] = float(elig['status'] == 'feasible')
    f['n_hard_missing'] = float(len(elig['missing']))
    f['n_hard_reasons'] = float(len(elig['reasons']))

    wa = _field(a, 'who_to_meet', t)
    wb = _field(b, 'who_to_meet', t)
    if wa is None or wb is None:
        f['who_meets_min'] = NAN
        f['who_meets_max'] = NAN
    else:
        flags = sorted((float(b['gender'] in wa), float(a['gender'] in wb)))
        f['who_meets_min'], f['who_meets_max'] = flags

    matches = 0
    observed_pairs = 0
    for key in SOFT:
        va = _field(a, key, t)
        vb = _field(b, key, t)
        seen = va is not None and vb is not None
        f['soft_%s_observed' % key] = float(seen)
        f['soft_%s_match' % key] = (float(va == vb) if seen else NAN)
        if seen:
            observed_pairs += 1
            matches += va == vb
    f['soft_match_count'] = float(matches)
    f['soft_observed_pairs'] = float(observed_pairs)

    weighted = 0.0
    covered = 0
    for key, w in WEIGHTS.items():
        va = _field(a, key, t)
        vb = _field(b, key, t)
        if va is not None and vb is not None:
            weighted += w * (1.0 if va == vb else -0.5)
            covered += 1
    f['weighted_soft_score'] = float(weighted)
    f['weighted_soft_covered'] = float(covered)

    since_a = float(t - a['arrived_day'])
    since_b = float(t - b['arrived_day'])
    f['day'] = float(t)
    f['days_since_arrival_mean'] = (since_a + since_b) / 2.0
    f['days_since_arrival_absdiff'] = abs(since_a - since_b)
    f['ask_budget'] = float(state['ask_budget_remaining'])

    ha = member_history(state, t, a_id)
    hb = member_history(state, t, b_id)
    for metric in HIST_METRICS:
        va, vb = float(ha[metric]), float(hb[metric])
        f['hist_%s_mean' % metric] = (va + vb) / 2.0
        f['hist_%s_absdiff' % metric] = abs(va - vb)

    available = sum(1 for m in state['members'] if m.get('available'))
    f['comp_available'] = float(available)
    f['comp_available_excl'] = float(max(0, available - 2))

    if set(f) != set(FEATURE_KEYS):
        raise AssertionError('feature set drift: %s' % sorted(set(f) ^ set(FEATURE_KEYS)))
    return {k: float(f[k]) for k in FEATURE_KEYS}


def memory_summary(state):
    """Restart-safe per-member counters from observable state only (v1 decisions do not read it)."""
    members = state.get('members') or []
    if not members:
        return {}
    day = state.get('day', 0)
    counts = {m['member_id']: [0, 0, 0, 0] for m in members}
    for intro in state.get('introductions') or []:
        for uid in (intro['user_a'], intro['user_b']):
            if uid in counts:
                counts[uid][0] += 1
    pair_of = {}
    for intro in state.get('introductions') or []:
        pair_of[intro['introduction_id']] = (intro['user_a'], intro['user_b'])
    for ev in state.get('feedback') or []:
        observed = ev.get('observed_day')
        if observed is None or observed > day:
            continue
        if ev.get('event') == 'date_happened' and ev.get('value'):
            for uid in pair_of.get(ev.get('introduction_id'), ()):
                if uid in counts:
                    counts[uid][1] += 1
        elif ev.get('event') == 'second_meeting_intention':
            uid = ev.get('member_id')
            if uid in counts:
                if ev.get('value') == 'yes':
                    counts[uid][2] += 1
                elif ev.get('value') == 'no':
                    counts[uid][3] += 1
    return {'v': 1, 'm': counts}



def _past_pairs(state):
    return {tuple(sorted((i['user_a'], i['user_b'])))
            for i in state.get('introductions') or []}


def ac_asks(state):
    """Rule-based selective clarification (spec section 7): tier1 blocked flips,
    tier1b progressive completion, tier2 soft completion. Budget-capped, deterministic."""
    try:
        budget = int(state.get('ask_budget_remaining') or 0)
        avail = sorted((m for m in state['members'] if m['available']),
                       key=lambda m: m['member_id'])
        past = _past_pairs(state)
        asks = []
        spent = 0

        def hard_missing(m):
            return any(m['field_status'][k] == 'not_asked' for k in kit.HARD)

        def pair_past(a, b):
            return tuple(sorted((a, b))) in past

        tier1 = []
        for m in avail:
            if not hard_missing(m):
                continue
            blocked = 0
            for o in avail:
                if o['member_id'] == m['member_id'] or pair_past(m['member_id'], o['member_id']):
                    continue
                if not all(o['fields'][k] is not None for k in kit.HARD):
                    continue
                if eligibility(m, o)['status'] == 'needs_clarification':
                    blocked += 1
            if blocked:
                tier1.append((-blocked, m['member_id']))
        for _, mid in sorted(tier1):
            if spent + 3 > budget:
                break
            asks.append({'member_id': mid, 'field': 'constraints'})
            spent += 3

        asked_constraints = {a['member_id'] for a in asks}
        tier1b = []
        for m in avail:
            if m['member_id'] in asked_constraints or not hard_missing(m):
                continue
            has_partner = any(o['member_id'] != m['member_id']
                              and not pair_past(m['member_id'], o['member_id'])
                              for o in avail)
            if not has_partner:
                continue
            n_missing = sum(1 for k in kit.HARD if m['field_status'][k] == 'not_asked')
            tier1b.append((n_missing, m['member_id']))
        for _, mid in sorted(tier1b):
            if spent + 3 > budget:
                break
            asks.append({'member_id': mid, 'field': 'constraints'})
            spent += 3

        for field in ('relationship_goal', 'relationship_pace'):
            tier2 = []
            for m in avail:
                if m['field_status'][field] != 'not_asked':
                    continue
                partners = 0
                for o in avail:
                    if o['member_id'] == m['member_id'] or pair_past(m['member_id'], o['member_id']):
                        continue
                    if eligibility(m, o)['status'] != 'feasible':
                        continue
                    if o['fields'][field] is not None:
                        partners += 1
                if partners:
                    tier2.append((-partners, m['member_id']))
            for _, mid in sorted(tier2):
                if spent + 1 > budget:
                    break
                asks.append({'member_id': mid, 'field': field})
                spent += 1
        return asks
    except Exception:
        return []



def rule_score(state, a_id, b_id):
    """Deterministic observable heuristic (fallback + T1 tie ordering): availability >
    feasibility > soft agreement. Never raises; NaN-guarded."""
    by_id = {m['member_id']: m for m in state['members']}
    a, b = by_id.get(a_id), by_id.get(b_id)
    if a is None or b is None or not a['available'] or not b['available']:
        return -1.0
    status = eligibility(a, b)['status']
    if status == 'infeasible':
        return -1.0
    score = 1.0 if status == 'feasible' else 0.5
    try:
        f = pair_features(state, a_id, b_id, state.get('day', 0))
        v = f.get('soft_match_count')
        if v is not None and v == v:          # NaN guard: nan != nan
            score += 0.01 * float(v)
    except Exception:
        pass
    return score


def _rule_greedy(edges):
    """Deterministic no-floor greedy fallback: sort by (-score, a, b), disjoint pairs.
    ONE member pool: occupancy is a single 'used' set (either endpoint consumes a member)."""
    picked, used = [], set()
    for a, b, s in sorted(edges, key=lambda e: (-e[2], e[0], e[1])):
        if a in used or b in used:
            continue
        picked.append((a, b, s))
        used.add(a)
        used.add(b)
    return picked


def _canon(a, b):
    """Orientation-free edge key: (min, max)."""
    return (a, b) if a <= b else (b, a)


def max_score_matching(nodes, edges, floor):
    """Greedy seed by (-score, a, b) + up to 8 deterministic strictly-improving local moves.

    GENERAL GRAPH: one member pool - a member may be either endpoint of any edge.
    Occupancy is a single partner map (node -> (other, score)); edge lookups use
    canonical keys _canon(a, b) so orientation never matters; a member is never in
    two kept edges (kit.advance raises 'overlapping allocation' otherwise).
    Returns unique (a, b, score), every score >= floor, sorted by (a, b).
    All candidate edges below floor -> [] (conservative wait, spec section 9).
    """
    if not edges:
        return []
    valid = set(nodes)
    above = sorted((e for e in edges
                    if e[0] in valid and e[1] in valid and e[0] != e[1]
                    and e[2] >= floor),
                   key=lambda e: (-e[2], e[0], e[1]))
    if not above:
        return []
    score_of = {}
    for a, b, s in above:                  # canonical key; first in (-score, a, b) wins
        score_of.setdefault(_canon(a, b), s)
    partner = {}                           # node -> (other_node, score): one pool
    for a, b, s in above:                  # greedy seed
        if a in partner or b in partner:
            continue
        partner[a] = (b, s)
        partner[b] = (a, s)

    def as_list():
        seen, out = set(), []
        for a, (b, s) in partner.items():  # each kept edge appears twice in partner
            k = _canon(a, b)
            if k in seen:
                continue
            seen.add(k)
            out.append((k[0], k[1], s))
        return sorted(out, key=lambda e: (e[0], e[1]))

    for _ in range(8):
        improved = False
        # move (a): add a free-free edge
        for a, b, s in above:
            if a not in partner and b not in partner:
                partner[a] = (b, s)
                partner[b] = (a, s)
                improved = True
                break
        if improved:
            continue
        # move (b): one matched endpoint switches onto a free node (strict gain),
        # checked in BOTH edge orientations so either endpoint can be the mover
        for a, b2, s2 in above:
            if a in partner and b2 not in partner and s2 > partner[a][1]:
                b1 = partner[a][0]
                del partner[b1]            # old partner becomes free
                partner[a] = (b2, s2)
                partner[b2] = (a, s2)
                improved = True
                break
            if b2 in partner and a not in partner and s2 > partner[b2][1]:
                a1 = partner[b2][0]
                del partner[a1]
                partner[b2] = (a, s2)
                partner[a] = (b2, s2)
                improved = True
                break
        if improved:
            continue
        # move (c): 2-cycle exchange between two kept edges (strict gain)
        m_pairs = sorted({_canon(a, b) for a, (b, _) in partner.items()})
        found = None
        for i, (a1, b1) in enumerate(m_pairs):
            s1 = partner[a1][1]
            for a2, b2 in m_pairs[i + 1:]:
                s2 = partner[a2][1]
                s12 = score_of.get(_canon(a1, b2))
                s21 = score_of.get(_canon(a2, b1))
                if s12 is not None and s21 is not None and s12 + s21 > s1 + s2:
                    found = (a1, b1, a2, b2, s12, s21)
                    break
            if found:
                break
        if found:
            a1, b1, a2, b2, s12, s21 = found
            for n in (a1, b1, a2, b2):
                partner.pop(n, None)
            partner[a1] = (b2, s12)
            partner[b2] = (a1, s12)
            partner[a2] = (b1, s21)
            partner[b1] = (a2, s21)
            improved = True
        if not improved:
            break
    return as_list()


def _score_pair(model, state, a_id, b_id):
    """Ranking score for one candidate pair. Test seam - patch this, not internals.
    Pure by design: exceptions propagate so ac_match can switch to the rule fallback."""
    f = pair_features(state, a_id, b_id, state.get('day', 0))
    return score_row(model, [f[k] for k in FEATURE_KEYS])


def ac_match(state):
    """Floor-gated approximate max-score global matching (spec sections 5.2, 9).

    Returns sorted [[a, b], ...] - the exact shape evaluate.validate_response accepts.
    Candidate pairs: available members, kit-feasible, never previously introduced.
    Model path: floor-gated max_score_matching. Fallback (blob missing/corrupt or
    scoring exception): deterministic no-floor rule greedy (spec T8).
    """
    try:
        members = sorted((m for m in state['members'] if m['available']),
                         key=lambda m: m['member_id'])
        if not members:
            return []
        past = _past_pairs(state)
        cand = []
        for i, a in enumerate(members):
            for b in members[i + 1:]:
                key = tuple(sorted((a['member_id'], b['member_id'])))
                if key in past:
                    continue
                if eligibility(a, b)['status'] != 'feasible':
                    continue
                cand.append((a['member_id'], b['member_id']))
        if not cand:
            return []
        if len(cand) > 12000:  # C7 count-based cap (spec 8): top 12,000 by (-rule_score, a, b) - never time-based
            cand = sorted(cand, key=lambda p: (-rule_score(state, p[0], p[1]), p[0], p[1]))[:12000]
        model = load_model()
        chosen = None
        if model is not None:
            try:
                edges = [(x, y, _score_pair(model, state, x, y)) for x, y in cand]
                chosen = max_score_matching([m['member_id'] for m in members],
                                            edges, float(model['floor']))
            except Exception:
                chosen = None                # scoring failure -> rule fallback (T8)
        if chosen is None:
            chosen = _rule_greedy([(x, y, rule_score(state, x, y)) for x, y in cand])
        return [[a, b] for a, b, _ in sorted(chosen, key=lambda e: (e[0], e[1]))]
    except Exception:
        return []

def build_parser():
    parser = argparse.ArgumentParser()
    parser.add_argument('--baseline', choices=['greedy', 'no_asks', 'random', 'ac'],
                        default='greedy')
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    request = json.load(sys.stdin)
    print(json.dumps(decide(request, args.baseline), allow_nan=False))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
